using FluentValidation;namespace Namaa.Application.JournalEntries.Commands.CreateJournalEntry;public sealed class CreateJournalEntryCommandValidator:AbstractValidator<CreateJournalEntryCommand>{public CreateJournalEntryCommandValidator(){RuleFor(x=>x.EntryNumber).NotEmpty().MaximumLength(30);RuleFor(x=>x.CreatedByUserId).GreaterThan(0);RuleFor(x=>x.Description).MaximumLength(1000);RuleFor(x=>x.SourceType).MaximumLength(50);RuleFor(x=>x.SourceId).GreaterThan(0).When(x=>x.SourceId.HasValue);}}
